functionImplementations.selectedEntity:
// Unable to retrieve the property in the normal way because the API only applies to generic dimensions
// Returns:
//  Entity ID in position 1 i.e. [0] e.g. [PPP_Entity].[H1].&[ND10]
//  Entity ID (simple) in position 2 i.e. [1] e.g. ND10
//  Entity classification in position 2 i.e. [2] e.g. "REFINERIE"

var resultList = ArrayUtils.create(Type.string);
var tableRS = Table_HelperEntity.getDataSource().getResultSet();

resultList[0] = tableRS[0]["PPP_Entity"].id;
resultList[1] = BusRules.simpleMemberID(resultList[0]);
resultList[2] = tableRS[0]["PPP_Entity"].properties["PPP_Entity.Classification"];

//console.log(resultList);
return (resultList);

